TLM.f("Sancti/10-03",{"officium":"S. Theresiæ a Jesu Infante Virginis","rule":["vide C6;","Gloria"],"ruleInherited":["Gloria"],"fallback":"Commune/C6","sections":{"Introitus":[{"k":"ref","la":"Cant 4:8-9"},{"k":"text","la":"Veni de Líbano, sponsa mea, veni de Líbano, veni: vulnerásti cor meum, soror mea sponsa, vulnerásti cor meum."},{"k":"ref","la":"Ps 112:1"},{"k":"text","la":"Laudáte, púeri, Dóminum: laudáte nomen Dómini."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Veni de Líbano, sponsa mea, veni de Líbano, veni: vulnerásti cor meum, soror mea sponsa, vulnerásti cor meum."}],"Oratio":[{"k":"text","la":"Dómine, qui dixísti: Nisi efficiámini sicut párvuli, non intrábitis in regnum cœlórum: da nobis, quǽsumus: ita sanctæ Teresiæ Vírginis in humilitáte et simplicitáte cordis vestígia sectári, ut præmia consequámur ætérna."},{"k":"macro","name":"Qui vivis"}],"Lectio":[{"k":"text","la":"Léctio Isaíæ Prophétæ"},{"k":"ref","la":"Is 66:12-14"},{"k":"text","la":"Hæc dicit Dóminus: Ecce, ego declinábo super eam quasi flúvium pacis, et quasi torréntem inundántem glóriam géntium, quam sugétis: ad úbera portabímini, et super génua blandiéntur vobis. Quómodo si cui mater blandiátur, ita ego consolábor vos, et in Jerúsalem consolabímini. Vidébitis, et gaudébit cor vestrum, et ossa vestra quasi herba germinábunt, et cognoscétur manus Dómini servis ejus."}],"Graduale":[{"k":"ref","la":"Matt 11:25"},{"k":"text","la":"Confíteor tibi, Pater, Dómine cœli et terræ, quia abscondísti hæc a sapiéntibus, et prudéntibus, et revelásti ea párvulis."},{"k":"ref","la":"Ps 70:5"},{"k":"text","la":"Dómine, spes mea a juventúte mea."},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 39:17-19"},{"k":"text","la":"Quasi rosa plantáta super rivos aquárum fructificate: quasi Libanus odórem suavitátis habete: florete, flores, quasi lílium, et date odórem, et frondete in grátiam, et collaudate cánticum, et benedicite Dóminum in opéribus suis. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Eccli 39:17-19"},{"k":"text","la":"Quasi rosa plantáta super rivos aquárum fructificáte: quasi Libánus odórem suavitátis habéte: floréte, flores, quasi lílium, et date odórem, et frondéte in grátiam, et collaudáte cánticum, et benedícite Dóminum in opéribus suis. Allelúja.","mark":"V"},{"k":"ref","la":"Ps 33:9; 99:5"},{"k":"text","la":"Gustáte, et vidéte quóniam suávis estDóminus: in ætérnum misericórdia ejus. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Cant 2:11-12"},{"k":"text","la":"Jam hiems tránsiit, imber ábiit, et recéssit."},{"k":"text","la":"Flores apparuérunt in terra nostra, tempus putatiónis advénit: vox túrturis audíta est in terra nostra.","mark":"V"},{"k":"ref","la":"Jer 31:3"},{"k":"text","la":"In caritáte perpétua diléxi te: ídeo attráxi te, míserans tui."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 18:1-4"},{"k":"text","la":"In illo témpore: Accessérunt discípuli ad Jesum, dicéntes: Quis, putas, major est in regno cœlórum? Et advocans Jesus párvulum, státuit eum in médio eórum, et dixit; Amen, dico vobis, nisi convérsi fuéritis, et efficiámini sicut párvuli, non intrábitis in regnum cœlorum. Quicúmque ergo humiliáverit se sicut párvulus iste, hic est major in regno cœlórum."}],"Offertorium":[{"k":"ref","la":"Luc 1:46-49"},{"k":"text","la":"Magníficat ánima mea Dóminum: et exsultávit spíritus meus in Deo salutári meo: quia respéxit humilitátem ancíllæ suæ: fecit mihi magna qui potens est."}],"Secreta":[{"k":"text","la":"Sacrifícium nostrum tibi, Dómine, quǽsumus, sanctæ Terésiæ Vírginis tuæ precátio sancta concíliet: ut, in cujus honóre sollémniter exhibétur, ejus méritis efficiátur accéptum."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Deut 32:10-12"},{"k":"text","la":"Circumdúxit eam, et dócuit: et custodívit quasi pupíllam óculi sui. Sicut aquila expándit alas suas, et assúmpsit eam, atque portávit in húmeris suis. Dóminus solus dux ejus fuit."}],"Postcommunio":[{"k":"text","la":"Illo nos, Dómine amóris igne cœléste mystérium inflámmet: quo sancta Teresia Virgo tua se tibi pro homínibus caritátis víctimam devóvit."},{"k":"macro","name":"Per Dominum"}]},"hr":{"1a1ac6142e307f51":{"t":"Pj 4, 8-9, Ps 112, 1\n(Pj 4, 8-9) Dođi s Libana, zaručnice moja, dođi s Libana, dođi! Ranila si srce moje, sestro moja, zaručnice, ranila si srce moje! (Ps 112, 1) Hvalite, djeco, Gospodina, hvalite ime Gospodnje.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Pj 4, 8-9) Dođi s Libana, zaručnice moja, dođi s Libana, dođi! Ranila si srce moje, sestro moja, zaručnice, ranila si srce moje!","kn":"(Caint. 4, 8-9). Dođi e Lihena, zaručnice moja, dođi s Libana, dođi-: ranila si srce moje, sestro moja, zairučnice, ranila si srce moje. (Ps. 112, 1) Hva^ lite, djeco, Gospodina: hvalite ime Gospodnje. Slava Ocu . . . Dođi ...","knRef":"Kniewald 1942, str. 724–725 (snimka 363) (OCR)"},"87c595f7e097d134":{"t":"<i>Pomolimo se</i>.\nGospodine, koji si rekao: Ako ne postanete kao djeca, nećete ući u kraljevstvo nebesko, daj nam, molimo, tako ići u poniznosti i jednostavnosti srca stopama svete Terezije djevice da postignemo vječne nagrade:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Gospodine, koji si rekao: Ako ne budete kao djeca, ne . čete ući u kraljevstvo nebesko, daj nam, molimo, tako slijediti put svete Terezlje u poniznosti i prostodušnosti srca', da zaslužimo vječnu nagradu; koji živiš i kraljuješ ...","knRef":"Kniewald 1942, str. 724–725 (snimka 363) (OCR)"},"6414caf460950d06":{"t":"Iz 66, 12-14\nČitanje Izaije proroka. Ovo govori Gospodin: Evo, dovest ću nad nju slavu naroda kao rijeku mira i kao bujan potok. Hranit će vas mlijekom, nositi na grudima i milovati na koljenima. Kao što nekoga miluje majka, tako ću i ja milovati vas i bit ću vaša utjeha u Jeruzalemu. Vidjet ćete i radovat će se vaše srce, a vaše će se kosti pomladiti kao trava i ruka će se Gospodnja pokazati na svojim službenicima.","kn":"Čitanje proroka Izaije (66, 12-14). Ovako govori Gospodin: Evo dovest ću nad nju slavu naroda kao rijeku mira i kao bujan potok. Hranit ću vas mlijekom, nositi na grudima i milovati na koljenima. Kao kad koga miluje majka, tako ću tješiti i ja vas 1 bit ću vaša utjeha u Jeruzalemu. Vidjet ćete i radovat će se, vaše srče, a pomladit će se kao trava vaše kosti i ruka će se Gospodnja pokazati za njegove službenike.","knRef":"Kniewald 1942, str. 724–725 (snimka 363) (OCR)"},"4b55e589cdbab7bf":{"t":"Mt 11, 25, Ps 70, 5\n(Mt 11, 25) Zahvaljujem ti, Oče, Gospodaru neba i zemlje, jer si ovo sakrio od mudrih i razumnih, a objavio si malenima. (Ps 70, 5) Gospodine, nado moja od mladosti moje.\n\nSir 39, 17-19\n<i>Aleluja</i>, <i>aleluja</i>.\nRastite kao ruža. pokraj potoka, neka vam miris bude kao miomiris Libana! Cvati, cvijeće, kao ljiljan i daj miris! Zeleni se miljem, pjevaj pjesmu hvale i blagoslivljaj Gospodina u njegovim djelima. <i>Aleluja</i>.","kn":"(Mt. 11, 25). Hvalu ti uzdajein. Oče, Goispodine neba i zemlje, što si sakrio ovo od učenih i mudrih a otkrio malenima. (Ps. 70, 5). Gospodine, nado moja od mladosti moje.\n\n<i>Aleluja</i>, <i>aleluja</i>.\n(Eceli. 39, 17-19). Rastite kao ruža usađena na obalama voda: kao Liban imajte ugodan miris; cvatite cvijećem kao ljiljan i dajte miris, listajte u milosti i pjevajte pjesmu hvale i blagosivajte Gospoidlna u djelima njegovim, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 724–725 (snimka 363) (OCR)"},"bfd3545c67f2c965":{"t":"Mt 18, 1-4\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme, pristupe učenici k Isusu i upitaju ga: Što misliš, tko je najveći u nebeskom kraljevstvu? Isus nato pozva jedno malo dijete, postavi ga pred njih i reče: Zaista vam kažem: ako se ne obratite i ne postanete kao,djeca, nećete ući u nebesko kraljevstvo. Dakle, tko se ponizi kao ovo dijete, taj je najveći u nebeskom kraljevstvu.","kn":"t Slijedi sveto Evanđelje po Mateju (18, 1-4). U ono vrijeme pristupiše k Isusu njegovi uoeniici i upitaše ga,: Sto misliš, tko, je najveći U kraljevstvu nebeskom? Isus tada pozove dijete postavi ga pred njih i odgovori: Zaista, vam kažem: Ako se ne obratite i ne postanete kao djeca, ne ćete ući U kraljevstvo nebesko! Koji postane malen kao ovo dijete, taj je najveći u kraljevstvu nebeskom.","knRef":"Kniewald 1942, str. 724–725 (snimka 363) (OCR)"},"a6df481457ae4ef7":{"t":"Lk 1, 46-48 i 49\nVeliča duša moja Gospodina. I raduje duh moj u Bogu spasu mojemu. Što je pogledao na poniženje sluškinje svoje. Svesilni mi je učinio velike stvari.","kn":"Veliča duša moja Gosipodina, i obradova se duh moj u Bogu, Spasitelju mojemu: što pogleda na sniženost službenice svoje: učini mi velike stvari onaj, koji ^e silan.","knRef":"Kniewald 1942, str. 724–725 (snimka 363) (OCR)"},"98d2d0e78b6e6a4f":{"t":"Molimo, Gospodine, neka ti preporuči našu žrtvu molitva svete Terezije djevice da postane ugodna po zaslugama one na čiju čast se svečano prinosi.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo Te, Gospodine, da sveta molitva Tvoje djevice svete Terezije učini našu žrtvu Tebi ugodn,om, te bude primljena po zaslugama ome, kojoj je u čast ,svečamo prikazujemo; po G. n.","knRef":"Kniewald 1942, str. 724–725 (snimka 363) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"2c155461e53d5d58":{"t":"Pnz 32, 10-12\nVodio ju je i učio, i čuvao je kao zjenicu oka svoga. Raširio je kao orao krila svoja, podigao ju je i nosio na svojim ramenima. Sam Gospodin je bio vođa njezin.","kn":"(Deut. 32, 10). Vidio ju je i učinio: i čuvao je kao! zjenicu oka svoga. Kao orao raširio je krila svoja i podigao je, i ponio na ramenima svojim. Sam Gospodin bio je vodič njem.","knRef":"Kniewald 1942, str. 724–725 (snimka 363) (OCR)"},"7e0af7823351a8e8":{"t":"<i>Pomolimo se</i>.\nRaspalila, nas Gospodine nebeska tajna onim ognjem ljubavi po kojem se tvoja sveta djevica Terezija posvetila tebi kao žrtva ljubavi za ljude.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Rasplamtlle, Gospodine, nebeske tajne u nama onaj plamen ljubavi, koji je ponukao svetu Terezi ju. Tvoju djevicu, da Ti se preda kao žrtva ljubavi za ljud,e; po G, n.","knRef":"Kniewald 1942, str. 724–725 (snimka 363) (OCR)"}}});
